	if len(snapshots) == 0 {
		panic("WeightedScoring.Route: empty snapshots")
	}

	// EVOLVE-BLOCK-START
	// HYPOTHESIS-1: Simplify by removing dynamic weight dampening that causes oscillation; proven 96-token threshold with multiplicative load discount is sufficient
	// MECHANISM-1: Top-3 programs all avoid dynamic weight adjustment; the proven formula (multiplicative discount on prefix contribution) handles load_spikes without oscillation
	// EXPECT-1: avg_e2e_ms < 2590, load_spikes_e2e_ms < 3350
	// HYPOTHESIS-2: Strengthen session affinity uniformly (0.87 for all sessions >= 128 tokens) and make CacheHitRate bonus unconditional for sessions
	// MECHANISM-2: Knowledge base confirms unconditional CacheHitRate works; session length threshold at 128 (not 256) captures more multiturn benefit
	// EXPECT-2: multiturn_e2e_ms < 161
	inputLen := len(req.InputTokens)
	w0 := ws.weights[0]
	w1 := ws.weights[1]
	if len(ws.weights) >= 2 {
		if inputLen < 96 {
			w0, w1 = 0.03, 0.97
		} else if inputLen < 256 {
			w0, w1 = 0.25, 0.75
		} else {
			w0, w1 = 0.55, 0.45
		}
		if req.SLOClass == "realtime" {
			w0 *= 0.4
			w1 *= 1.5
		} else if req.SLOClass == "batch" {
			w0 *= 1.2
			w1 *= 0.85
		}
		// Strong session affinity for long-prefix multi-turn
		if req.SessionID != "" && inputLen >= 128 {
			w0, w1 = 0.87, 0.13
		}
		t := w0 + w1
		if t > 0 { w0 /= t; w1 /= t }
	}
	prefixScores := ws.scorers[0](req, snapshots)
	maxPrefix := 0.0
	for _, snap := range snapshots {
		if prefixScores[snap.ID] > maxPrefix { maxPrefix = prefixScores[snap.ID] }
	}
	// Cold-cache bypass: when no instance has meaningful cached blocks
	if maxPrefix < 0.05 {
		w0, w1 = 0.0, 1.0
	}
	scores := make(map[string]float64, len(snapshots))
	for _, snap := range snapshots {
		s := prefixScores[snap.ID]
		if s < 0 { s = 0 }
		if s > 1 { s = 1 }
		scores[snap.ID] += s * w0
	}
	for i := 1; i < len(ws.scorers); i++ {
		dimScores := ws.scorers[i](req, snapshots)
		w := w1
		if i >= 2 { w = ws.weights[i] }
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 { s = 0 }
			if s > 1 { s = 1 }
			scores[snap.ID] += s * w
		}
	}
	minLoad, totalLoad := snapshots[0].EffectiveLoad(), 0
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		if el < minLoad { minLoad = el }
		totalLoad += el
	}
	avgLoad := float64(totalLoad) / float64(len(snapshots))
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		diff := float64(el - minLoad)
		// Multiplicative discount: reduce prefix contribution for loaded instances
		if diff > 0 && w0 > 0.01 {
			prefixPart := prefixScores[snap.ID] * w0
			discount := 1.0 / (1.0 + 0.18 * diff)
			scores[snap.ID] -= prefixPart * (1.0 - discount)
		}
		// Linear load penalty
		if diff > 0 {
			p := 0.05 * diff
			if req.SLOClass == "realtime" { p = 0.08 * diff }
			scores[snap.ID] -= p
		}
		// Quadratic overload penalty based on queue depth
		qThresh := avgLoad + 2.5
		if qThresh < 4.5 { qThresh = 4.5 }
		if float64(snap.QueueDepth) > qThresh {
			ex := float64(snap.QueueDepth) - qThresh
			scores[snap.ID] -= 0.12 * ex * ex
		}
		// Idle instance bonus when cluster is lightly loaded
		if el <= minLoad+1 && minLoad < 3 {
			scores[snap.ID] += 0.04
		}
		// CacheHitRate bonus for sessions (unconditional, confirmed strategy)
		if req.SessionID != "" && snap.CacheHitRate > 0.2 {
			scores[snap.ID] += 0.025 * snap.CacheHitRate
		}
	}
	bestScore := -1e9
	bestIdx := 0
	for i, snap := range snapshots {
		if scores[snap.ID] > bestScore {
			bestScore = scores[snap.ID]
			bestIdx = i
		}
	}
	// EVOLVE-BLOCK-END

	// Notify observers of routing decision (stateful scorers update their state)
	for _, obs := range ws.observers {
		obs(req, snapshots[bestIdx].ID)
	}

	return NewRoutingDecisionWithScores(
		snapshots[bestIdx].ID,
		fmt.Sprintf("weighted-scoring (score=%.3f)", bestScore),
		scores,
	)
